import { satisfies } from './src/range.mjs';

const tests = [
  // Build metadata should be ignored
  ['1.2.3+build123', '1.2.3', true],
  ['1.2.3+build', '1.2.3+other', true],
  ['1.2.3-beta+build', '>=1.2.3-beta', true],

  // Prerelease precedence
  ['1.2.3-1', '>=1.2.3-2', false],  // numeric: 1 < 2
  ['1.2.3-alpha', '>=1.2.3-beta', false],  // alphabetic: alpha < beta
  ['1.2.3-1.2', '>=1.2.3-1.10', false],  // numeric: 2 < 10
  ['1.2.3-1.alpha', '>=1.2.3-1.1', true],  // numeric < non-numeric
  ['1.2.3-alpha', '>=1.2.3-1', false],  // numeric < non-numeric
  ['1.2.3-1', '>=1.2.3-alpha', true],  // numeric < non-numeric

  // Multiple prerelease identifiers
  ['1.2.3-alpha.1', '>=1.2.3-alpha', true],
  ['1.2.3-alpha', '>=1.2.3-alpha.1', false],  // fewer identifiers

  // Invalid versions should throw
  // ['abc', '1.2.3', null],  // skip TypeError tests for now
];

let passed = 0;
let failed = 0;

for (const [version, range, expected] of tests) {
  try {
    const result = satisfies(version, range);
    if (result === expected) {
      passed++;
      console.log('✓', version, 'satisfies', range);
    } else {
      failed++;
      console.log('✗', version, 'satisfies', range, '- got', result, 'expected', expected);
    }
  } catch (e) {
    failed++;
    console.log('✗', version, 'satisfies', range, '- ERROR:', e.message);
  }
}

console.log(\`\n\${passed} passed, \${failed} failed\`);

// Test that invalid versions throw TypeError
console.log('\nTesting error handling:');
try {
  satisfies('abc', '1.2.3');
  console.log('✗ Should throw TypeError for invalid version');
} catch (e) {
  if (e instanceof TypeError) {
    console.log('✓ Throws TypeError for invalid version');
  } else {
    console.log('✗ Wrong error type:', e);
  }
}

try {
  satisfies('1.2.3', '>=abc');
  console.log('✗ Should throw TypeError for invalid range version');
} catch (e) {
  if (e instanceof TypeError) {
    console.log('✓ Throws TypeError for invalid range version');
  } else {
    console.log('✗ Wrong error type:', e);
  }
}
